import{_ as t,c as a,o as i,aj as o}from"./chunks/framework.CDhdelVI.js";const m=JSON.parse('{"title":"New York Style Pizza (Home-Oven Optimized)","description":"A New York style pizza dough tuned for home ovens, with balanced chew, good browning, and foldable slices.","frontmatter":{"title":"New York Style Pizza (Home-Oven Optimized)","description":"A New York style pizza dough tuned for home ovens, with balanced chew, good browning, and foldable slices.","head":[["meta",{"name":"description","content":"A New York style pizza dough tuned for home ovens, with balanced chew, good browning, and foldable slices."}],["meta",{"property":"og:title","content":"New York Style Pizza (Home-Oven Optimized)"}],["meta",{"property":"og:description","content":"A New York style pizza dough tuned for home ovens, with balanced chew, good browning, and foldable slices."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/new-york-style-pizza.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"New York Style Pizza (Home-Oven Optimized)"}],["meta",{"name":"twitter:description","content":"A New York style pizza dough tuned for home ovens, with balanced chew, good browning, and foldable slices."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/new-york-style-pizza.html"}]]},"headers":[],"relativePath":"recipes/new-york-style-pizza.md","filePath":"recipes/new-york-style-pizza.md"}'),l={name:"recipes/new-york-style-pizza.md"};function r(n,e,s,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="new-york-style-pizza-home-oven-optimized" tabindex="-1">New York Style Pizza (Home-Oven Optimized) <a class="header-anchor" href="#new-york-style-pizza-home-oven-optimized" aria-label="Permalink to “New York Style Pizza (Home-Oven Optimized)”">​</a></h1><p>This is the home-oven version of the classic foldable slice: thin enough to bend, strong enough to hold toppings, and crisp on the bottom without turning cracker-dry. Use the <a href="https://kitchenratio.com/calculator" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch size.</p><div class="info custom-block"><p class="custom-block-title">Testing Status</p><p>This formula is still being tested and refined.</p></div><h2 id="baker-s-testing-range" tabindex="-1">Baker&#39;s % (Testing Range) <a class="header-anchor" href="#baker-s-testing-range" aria-label="Permalink to “Baker&#39;s % (Testing Range)”">​</a></h2><ul><li><strong>Flour</strong> - 100%</li><li><strong>Water</strong> - 60-62%</li><li><strong>Salt</strong> - 2.2-2.5%</li><li><strong>Olive oil</strong> - 1.5-2%</li><li><strong>Sugar</strong> - 0-2% (1% is a strong starting point)</li><li><strong>Yeast (IDY)</strong> - 0.2-0.4%</li></ul><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 500g (100%)</li><li><strong>Water</strong> - 305g (61%)</li><li><strong>Salt</strong> - 11.5g (2.3%)</li><li><strong>Olive oil</strong> - 9g (1.8%)</li><li><strong>Sugar</strong> - 5g (1%)</li><li><strong>Instant dry yeast</strong> - 1.5g (0.3%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This batch usually makes <strong>three 11-12 inch pizzas</strong>, depending on rim thickness.</p></div><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Combine flour, yeast, sugar, and about 90% of the water.</li><li>Mix until no dry flour remains. Rest 10 minutes.</li><li>Add salt, olive oil, and remaining water. Mix to a cohesive dough.</li><li>Knead <strong>4-6 minutes</strong> to moderate gluten development.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>You want moderate development, not full windowpane. The cold fermentation will finish the job.</p></div><h3 id="_2-divide-and-ball" tabindex="-1">2. Divide and Ball <a class="header-anchor" href="#_2-divide-and-ball" aria-label="Permalink to “2. Divide and Ball”">​</a></h3><ul><li>Divide immediately after mixing.</li><li>Ball tightly with smooth seams underneath.</li><li>Place in lightly oiled covered containers.</li></ul><h3 id="_3-cold-fermentation" tabindex="-1">3. Cold Fermentation <a class="header-anchor" href="#_3-cold-fermentation" aria-label="Permalink to “3. Cold Fermentation”">​</a></h3><ul><li>Refrigerate dough balls for <strong>24-72 hours</strong>.</li><li>The sweet spot for flavor and handling is often <strong>48 hours</strong>.</li></ul><h3 id="_4-temper-before-stretching" tabindex="-1">4. Temper Before Stretching <a class="header-anchor" href="#_4-temper-before-stretching" aria-label="Permalink to “4. Temper Before Stretching”">​</a></h3><ul><li>Remove dough balls from the refrigerator <strong>1.5-2 hours</strong> before baking.</li><li>Dough should feel cool, extensible, and relaxed.</li></ul><h3 id="_5-stretch-and-top" tabindex="-1">5. Stretch and Top <a class="header-anchor" href="#_5-stretch-and-top" aria-label="Permalink to “5. Stretch and Top”">​</a></h3><ul><li>Dust bench with flour (or a flour/semolina blend).</li><li>Press from center outward and leave a small rim.</li><li>Stretch to final size without crushing all gas.</li><li>Top with a light hand. Overloading kills the foldable slice profile.</li></ul><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Launch from a peel with enough bench flour to slide, but not so much that the bottom burns on steel.</p></div><h3 id="_6-bake-steel-home-oven" tabindex="-1">6. Bake (Steel, Home Oven) <a class="header-anchor" href="#_6-bake-steel-home-oven" aria-label="Permalink to “6. Bake (Steel, Home Oven)”">​</a></h3><ul><li>Preheat baking steel for <strong>45-60 minutes</strong> at <strong>500-550F</strong>.</li><li>Bake until underside is browned and top is well set, usually <strong>5-8 minutes</strong> depending on oven.</li><li>If top color lags, finish under broiler for <strong>30-90 seconds</strong>.</li></ul><h3 id="_7-rest-and-slice" tabindex="-1">7. Rest and Slice <a class="header-anchor" href="#_7-rest-and-slice" aria-label="Permalink to “7. Rest and Slice”">​</a></h3><ul><li>Rest pizza <strong>2-3 minutes</strong> before slicing.</li><li>This keeps cheese from flooding and preserves structure.</li></ul><h2 id="what-to-adjust-first" tabindex="-1">What to Adjust First <a class="header-anchor" href="#what-to-adjust-first" aria-label="Permalink to “What to Adjust First”">​</a></h2><ul><li><strong>Too pale on bottom</strong>: longer preheat, lower rack position, or slightly less dough weight.</li><li><strong>Too stiff to stretch</strong>: add 1-2% water or extend warm-up time.</li><li><strong>Weak and sticky</strong>: lower hydration toward 60% or tighten balling.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/fermentation.html">Fermentation</a></li><li><a href="/ingredients/flour.html">Flour</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul><h2 id="related-recipes" tabindex="-1">Related Recipes <a class="header-anchor" href="#related-recipes" aria-label="Permalink to “Related Recipes”">​</a></h2><ul><li><a href="/recipes/colorado-pizza-dough.html">Colorado Style Pizza Dough</a></li><li><a href="/recipes/roman-al-taglio-pizza.html">Roman Pizza al Taglio (High Hydration)</a></li></ul><hr><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',37)])])}const u=t(l,[["render",r]]);export{m as __pageData,u as default};
